# Review package: d85d117..b4c5579

## Commits
b4c5579 test: cover full stop-word list and typographic closing quotes

## Files changed
 test/sentenceCount.test.js |  2 ++
 test/topWords.test.js      | 13 +++++++++++++
 2 files changed, 15 insertions(+)

## Diff
diff --git a/test/sentenceCount.test.js b/test/sentenceCount.test.js
index 5aff80e..4ca9b4a 100644
--- a/test/sentenceCount.test.js
+++ b/test/sentenceCount.test.js
@@ -98,20 +98,22 @@ test('does not split a decimal number', () => {
 });

 test('does not split a domain name or a dotted name', () => {
   assert.equal(sentenceCount('Visit example.com today. Bye.'), 2);
   assert.equal(sentenceCount('The id a.b.c is valid. Bye.'), 2);
 });

 test('ends a sentence at a terminator followed by a closing quote', () => {
   assert.equal(sentenceCount('He said "Go." Then he left.'), 2);
   assert.equal(sentenceCount("She said 'Why?' Then she left."), 2);
+  assert.equal(sentenceCount('He said “Go.” Then he left.'), 2);
+  assert.equal(sentenceCount('She said ‘Stop.’ Then she ran.'), 2);
 });

 test('ends a sentence at a terminator followed by a closing bracket', () => {
   assert.equal(sentenceCount('(See above.) Next one.'), 2);
   assert.equal(sentenceCount('Items [one!] two.'), 2);
 });

 test('returns 0 for a text made only of terminators', () => {
   assert.equal(sentenceCount('!!! ... ???'), 0);
 });
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 58c6965..a64a45e 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -156,10 +156,23 @@ test('checks the text before n', () => {
 test('returns fresh objects on every call', () => {
   const first = topWords('apple apple pear', 2);
   first[0].count = 99;
   first[1].word = 'changed';
   first.pop();
   assert.deepEqual(topWords('apple apple pear', 2), [
     { word: 'apple', count: 2 },
     { word: 'pear', count: 1 },
   ]);
 });
+
+test('skips every one of the 36 stop words listed in the plan', () => {
+  const planStopWords = [
+    'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
+    'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
+    'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
+    'will', 'with',
+  ];
+  assert.equal(planStopWords.length, 36);
+  for (const word of planStopWords) {
+    assert.deepEqual(topWords(word, 5), [], `stop word "${word}" was not skipped`);
+  }
+});

